func (r *QueryResolver) ShipmentDriverFeasibility(ctx context.Context, shipmentID string) ([]*gqlmodel.DriverFeasibility, error) {
	authCtx, err := r.RequirePermission(ctx, permission.ResourceShipment, permission.OpRead)
	if err != nil {
		return nil, err
	}

	id, err := pulid.Parse(shipmentID)
	if err != nil {
		return nil, err
	}

	entity, err := r.ShipmentReader.Get(ctx, &shipmentports.GetShipmentByIDRequest{
		ID:         id,
		TenantInfo: resolvercore.TenantInfo(authCtx),
		ShipmentOptions: shipmentports.ShipmentOptions{
			ExpandShipmentDetails: true,
		},
	})
	if err != nil {
		return nil, err
	}

	req := &telematicsservice.FeasibilityRequest{TenantInfo: resolvercore.TenantInfo(authCtx)}
	for _, move := range entity.Moves {
		if move == nil || move.Distance == nil {
			continue
		}
		req.TotalMiles += *move.Distance
	}
	if firstStop := shipment.FirstShipperStop(entity.Moves); firstStop != nil &&
		firstStop.Location != nil &&
		firstStop.Location.Latitude != nil &&
		firstStop.Location.Longitude != nil {
		req.FirstStop = &telematicsservice.FeasibilityPoint{
			Latitude:  *firstStop.Location.Latitude,
			Longitude: *firstStop.Location.Longitude,
		}
	}

	results, err := r.TelematicsService.EvaluateDriverFeasibility(ctx, req)
	if err != nil {
		return nil, err
	}

	out := make([]*gqlmodel.DriverFeasibility, 0, len(results))
	for _, result := range results {
		out = append(out, mapDriverFeasibility(result))
	}
	return out, nil
}

